const cfg = $('Build Config').first().json.config;
const raw = $('Settings').first().json;
const tz = cfg.timezone || 'Asia/Karachi';
const c = k => String(raw[k] ?? '').trim();
const perm = c('Sharing Permission');
const anonymous = perm === 'Anonymous only';
let ok = true;
let msg = '';
if (perm === 'Internal only (no content)') {
  ok = false;
  msg = '🔒 Ye project "Internal only" hai, isliye public content nahi banaya gaya aur kuch store bhi nahi hua.';
} else if (c('Problem').length < 30 || c('Solution Built').length < 30 || c('Results').length < 15) {
  ok = false;
  msg = '✍️ Details kam hain. Problem aur Solution kam az kam 30 characters, Results kam az kam 15 characters me likho, phir form dobara bhejo.';
}
return [{ json: {
  ok, msg,
  cs_id: 'CS-' + String(Date.now()).slice(-8),
  created_at: new Date().toLocaleString('sv-SE', { timeZone: tz }),
  title: c('Project Title'),
  client_name: c('Client Name'),
  stored_client_name: perm === 'Name can be shared' ? c('Client Name') : '',
  industry: c('Industry'),
  problem: c('Problem'),
  solution: c('Solution Built'),
  tools: c('Tools Used'),
  results: c('Results'),
  permission: perm,
  anonymous,
  link: c('Project Link')
} }];

