const parseJSON = raw => {
  const cleaned = String(raw || '').replace(/```json|```/g, '').trim();
  try { return JSON.parse(cleaned); } catch (e) {}
  const m = cleaned.match(/\{[\s\S]*\}/);
  if (!m) return null;
  try { return JSON.parse(m[0]); } catch (e) { return null; }
};
const d = parseJSON($input.first().json.text || $input.first().json.output || '');
if (!d || !d.linkedin || !d.carousel || !d.fiverr) throw new Error('Content pack JSON parse nahi hua');
const cs = $('Normalize Case').first().json;
const warnings = [];
let scrubbed = false;
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const scrub = t => {
  const s = String(t ?? '');
  if (cs.anonymous && cs.client_name && cs.client_name.length > 1) {
    const re = new RegExp(esc(cs.client_name), 'gi');
    if (re.test(s)) { scrubbed = true; return s.replace(re, 'the client'); }
  }
  return s;
};
const li = d.linkedin;
const hook = scrub(li.hook).trim();
let body = scrub(li.body).trim();
if (!hook || body.length < 250) throw new Error('LinkedIn draft incomplete ya bohat chhota hai');
if (body.startsWith(hook)) body = body.slice(hook.length).trim();
const tags = (Array.isArray(li.hashtags) ? li.hashtags : String(li.hashtags || '').split(/\s+/))
  .map(t => String(t).trim()).filter(Boolean).map(t => (t.startsWith('#') ? t : '#' + t)).slice(0, 5).join(' ');
const finalPost = `${hook}\n\n${body}\n\n${tags}`;
if (finalPost.length > 3000) throw new Error('LinkedIn draft 3000 characters se zyada hai');
const slides = (Array.isArray(d.carousel.slides) ? d.carousel.slides : []).slice(0, 8)
  .map(s => ({ title: scrub(s.title).trim(), text: scrub(s.text).trim() }));
if (slides.length < 6) throw new Error('Carousel outline incomplete hai');
const fv = d.fiverr;
const fiverr = {
  title: scrub(fv.title).trim().slice(0, 80),
  description: scrub(fv.description).trim().slice(0, 1000),
  tags: (Array.isArray(fv.tags) ? fv.tags : []).map(t => scrub(t).trim()).filter(Boolean).slice(0, 5)
};
// fact guard: flag significant numbers that are not in the form input
const source = [cs.title, cs.problem, cs.solution, cs.tools, cs.results].join(' ').toLowerCase().replace(/,/g, '');
const allText = [finalPost, slides.map(s => s.title + ' ' + s.text).join(' '), fiverr.title, fiverr.description].join(' ');
const nums = allText.match(/\$?\d[\d,]*\.?\d*\s?(%|x|k|m)?/gi) || [];
const unverified = [...new Set(nums.map(n => n.trim()).filter(n => {
  const digits = n.replace(/[^\d.]/g, '').replace(/\.$/, '');
  if (!digits) return false;
  const significant = /[%$]/.test(n) || digits.replace('.', '').length >= 2;
  if (!significant || /^(19|20)\d\d$/.test(digits)) return false;
  return !source.includes(digits);
}))];
if (unverified.length) warnings.push('Ye numbers form ke input me nahi mile, post karne se pehle verify karo: ' + unverified.join(', '));
if (scrubbed) warnings.push('Client ka naam anonymous project me scrub kiya gaya.');
return [{ json: {
  hook, hashtags: tags, final_post: finalPost, slides,
  carousel_json: JSON.stringify(slides),
  fiverr, fiverr_tags: fiverr.tags.join(', '),
  warnings, warnings_text: warnings.join(' | '),
  status: 'Pending Approval'
} }];

