const cfg = $('Build Config').first().json.config;
const rows = $input.all().map(i => i.json).filter(r => r.id);
const tz = cfg.timezone || 'Asia/Karachi';
const today = new Date().toLocaleDateString('en-CA', { timeZone: tz });
const max = parseInt(cfg.max_posts_per_day || '1', 10) || 1;
const count = rows.filter(r => String(r.created_at || '').slice(0, 10) === today && r.status !== 'Rejected').length;
